public class ByteVector {
    private byte[] data;
    private int capacity;

    public ByteVector(int initialCapacity) {
        this.capacity = initialCapacity;
        this.data = new byte[capacity];
    }

    private void enlarge(final int size) {
        int newCapacity = capacity + size;
        byte[] newData = Arrays.copyOf(data, newCapacity);
        this.data = newData;
        this.capacity = newCapacity;
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector(5);
        System.out.println("Initial capacity: " + byteVector.capacity);
        byteVector.enlarge(3);
        System.out.println("New capacity: " + byteVector.capacity);
    }
}

