public class TreeOperations {

    private TreeNode<T> rotateRight(TreeNode<T> node) {
        if (node == null || node.left == null) {
            return node;
        }

        TreeNode<T> newParent = node.left;
        node.left = newParent.right;
        newParent.right = node;

        return newParent;
    }

    public static void main(String[] args) {
        TreeOperations treeOps = new TreeOperations();
        TreeNode<Integer> root = new TreeNode<>(10);
        root.left = new TreeNode<>(5);
        root.right = new TreeNode<>(15);
        root.left.left = new TreeNode<>(3);
        root.left.right = new TreeNode<>(7);

        TreeNode<Integer> newRoot = treeOps.rotateRight(root.left);
        System.out.println("New root value: " + newRoot.value);
        System.out.println("New left child value: " + newRoot.left.value);
        System.out.println("New right child value: " + newRoot.right.value);
    }
}

