        inputFields.put("field1", "type1");
        inputFields.put("field2", "type2");
        inputFields.put("_source", "config");

        Mappings mappings = new Mappings(inputFields);
        Mappings diff = diffStructure("tableName", mappings);

        System.out.println(diff);
    }
}

