import java.util.Properties;

public class VariableSubstitutor {

    public static String findAndSubst(String key, Properties props) {
        String value = props.getProperty(key);
        if (value != null) {
            return substituteVariables(value, props);
        }
        return null;
    }

    private static String substituteVariables(String value, Properties props) {
        while (value.contains("${")) {
            int startIndex = value.indexOf("${");
            int endIndex = value.indexOf("}", startIndex);
            if (endIndex == -1) {
                break;
            }
            String variableName = value.substring(startIndex + 2, endIndex);
            String variableValue = props.getProperty(variableName);
            if (variableValue != null) {
                value = value.substring(0, startIndex) + variableValue + value.substring(endIndex + 1);
            } else {
                break;
            }
        }
        return value;
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("name", "John");
        props.setProperty("greeting", "Hello, ${name}!");

        String result = findAndSubst("greeting", props);
        System.out.println(result); // Output: Hello, John!
    }
}

