private void pop(final String descriptor) {
    Stack<String> outputFrameStack = new Stack<>();
    // Simulate pushing some abstract types onto the stack
    outputFrameStack.push("Type1");
    outputFrameStack.push("Type2");
    outputFrameStack.push("Type3");

    // Determine the number of types to pop based on the descriptor
    int count = 0;
    for (char c : descriptor.toCharArray()) {
        if (c == 'L' || c == '[') {
            count++;
        } else if (c == ')') {
            break;
        }
    }

    // Pop the specified number of types from the stack
    for (int i = 0; i < count; i++) {
        if (!outputFrameStack.isEmpty()) {
            outputFrameStack.pop();
        }
    }

    // Output the remaining types on the stack
    System.out.println("Remaining types on stack: " + outputFrameStack);
}

