public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int capacity = desiredCapacity;
    boolean found = false;
    while (!found) {
        if (isPrime(capacity)) {
            found = true;
        } else {
            capacity++;
        }
        if (desiredCapacity >= 1000 && capacity - desiredCapacity > 0.11 * desiredCapacity) {
            break;
        }
    }
    return capacity;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    for (int i = 2; i <= Math.sqrt(number); i++) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}

