protected <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }

    V startVertex = null;
    for (E edge : tour) {
        Pair<V, V> endpoints = graph.getEdgeSource(edge), graph.getEdgeTarget(edge);
        if (startVertex == null) {
            startVertex = endpoints.getFirst();
        } else if (startVertex.equals(endpoints.getFirst())) {
            startVertex = endpoints.getSecond();
        }
    }

    if (startVertex == null) {
        return null;
    }

    GraphIterator<V, E> iterator = new BreadthFirstIterator<>(graph, startVertex);
    Set<V> visited = new HashSet<>();
    visited.add(startVertex);

    V currentVertex = startVertex;
    E currentEdge = null;
    while (iterator.hasNext()) {
        V nextVertex = iterator.next();
        if (tour.contains(graph.getEdge(currentVertex, nextVertex))) {
            currentEdge = graph.getEdge(currentVertex, nextVertex);
            currentVertex = nextVertex;
            visited.add(nextVertex);
        }
    }

    if (currentEdge == null) {
        return null;
    }

    return new GraphWalk<>(graph, startVertex, currentVertex, visited, tour);
}

