public class LinkedListImpl<E> {
    private ListNodeImpl<E> head;
    private ListNodeImpl<E> tail;

    public boolean unlink(ListNodeImpl<E> node) {
        if (node == null) {
            return false;
        }

        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            head = node.next;
        }

        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            tail = node.prev;
        }

        node.next = null;
        node.prev = null;

        return true;
    }

    public static void main(String[] args) {
        LinkedListImpl<Integer> list = new LinkedListImpl<>();
        ListNodeImpl<Integer> node1 = new ListNodeImpl<>(1);
        ListNodeImpl<Integer> node2 = new ListNodeImpl<>(2);
        ListNodeImpl<Integer> node3 = new ListNodeImpl<>(3);

        list.head = node1;
        node1.next = node2;
        node2.prev = node1;
        node2.next = node3;
        node3.prev = node2;

        list.unlink(node2);

        // Check if the unlink was successful
        if (list.head.value == 1 && list.head.next.value == 3 && list.head.next.prev.value == 1) {
            System.out.println("Unlink successful");
        } else {
            System.out.println("Unlink failed");
        }
    }
}

