import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;

public static Type resolveBound(TypeVariable<?> typeVariable) {
    Type genericDeclaration = typeVariable.getGenericDeclaration();
    if (genericDeclaration instanceof Class<?>) {
        Class<?> clazz = (Class<?>) genericDeclaration;
        Type[] genericInterfaces = clazz.getGenericInterfaces();
        for (Type genericInterface : genericInterfaces) {
            if (genericInterface instanceof ParameterizedType) {
                ParameterizedType parameterizedType = (ParameterizedType) genericInterface;
                Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
                for (Type actualTypeArgument : actualTypeArguments) {
                    if (actualTypeArgument instanceof TypeVariable) {
                        TypeVariable<?> typeVariableInInterface = (TypeVariable<?>) actualTypeArgument;
                        if (typeVariableInInterface.getName().equals(typeVariable.getName())) {
                            return parameterizedType.getActualTypeArguments()[0];
                        }
                    }
                }
            }
        }
    }
    return Unknown.class;
}

