private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true;
    }

    Iterator<V> iterator = vertices.iterator();
    V vertex1 = iterator.next();
    while (iterator.hasNext()) {
