import java.util.List;
import java.util.ArrayList;
import java.util.Map;
import java.util.HashMap;

private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    Map<K, Integer> keyBounds = new HashMap<>();

    for (K key : keys) {
        if (!keyBounds.containsKey(key)) {
            keyBounds.put(key, Integer.MIN_VALUE);
        }
        keyBounds.put(key, Math.max(keyBounds.get(key), key));
    }

    for (K key : keys) {
        upperBounds.add(keyBounds.get(key));
    }

    return upperBounds;
}

