import java.io.IOException;
import java.io.InputStream;

public class ProtocolBufferReader {
    private InputStream inputStream;

    public ProtocolBufferReader(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    public int readTag() throws IOException {
        int firstByte = inputStream.read();
        if (firstByte == -1) {
            return 0; // EOF
        }
        int tag = firstByte & 0x7F;
        int shift = 7;
        while ((firstByte & 0x80) != 0) {
            firstByte = inputStream.read();
            if (firstByte == -1) {
                throw new IOException("Protocol message contained a malformed tag (0x" + Integer.toHexString(firstByte) + ").");
            }
            tag |= (firstByte & 0x7F) << shift;
            shift += 7;
        }
        return tag;
    }
}

