public class ThreadSnapshotParser {

    public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine()) != null) {
                // Assuming each line represents a thread snapshot and contains a timestamp
                String[] parts = line.split(",");
                if (parts.length >= 2) {
                    long timestamp = Long.parseLong(parts[0]);
                    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                        if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                            ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, parts[1]);
                            threadSnapshots.add(snapshot);
                            break;
                        }
                    }
                }
            }
        }
        return threadSnapshots;
    }

